var fs = require("fs");
global.window = {};
eval(fs.readFileSync("/tmp/bench.js","utf8"));
var b = window.__bench;
var E = b.bodies[2], M = b.bodies.find(function(x){return x.name==="Mars";});
function au(body,d){ var a=((body.angleDeg0 + 360*d/body.periodDays)%360)*Math.PI/180; return {x:body.auRadius*Math.cos(a), y:body.auRadius*Math.sin(a)}; }
function dist(p,q){ return Math.hypot(p.x-q.x, p.y-q.y); }
var fails=0; function check(n,c){ console.log((c?"ok  ":"FAIL")+" "+n); if(!c)fails++; }

// 1) nave chega à posição real de Marte no dia de chegada
b.setMissionDay(b.mission.outboundDays);
var s=b.getState();
check("ship≈Mars @ "+s.missionDay, dist(s.shipAU, au(M, s.missionDay)) < 1e-9);

// 2) perto de Marte durante a estadia (metade)
b.setMissionDay(b.mission.outboundDays + b.mission.stayDays/2);
s=b.getState();
check("ship≈Mars @ mid-stay", dist(s.shipAU, au(M, s.missionDay)) < 1e-9);

// 3) perto da posição real de Terra no fim
b.setMissionDay(b.mission.totalDays);
s=b.getState();
check("ship≈Earth @ total", dist(s.shipAU, au(E, s.missionDay)) < 1e-9);

// 4) valores declarados
var m=b.mission;
check("outbound≈259  ("+m.outboundDays+")", Math.abs(m.outboundDays-259)<2);
check("stay≈455  ("+m.stayDays+")", Math.abs(m.stayDays-455)<3);
check("return≈259  ("+m.returnDays+")", Math.abs(m.returnDays-259)<2);
check("total≈970  ("+m.totalDays+")", Math.abs(m.totalDays-970)<8);
check("lead≈44  ("+m.departurePhaseAngleDeg+")", Math.abs(m.departurePhaseAngleDeg-44.3)<1.5);
check("ratio M/E≈1.88  ("+(M.periodDays/E.periodDays).toFixed(4)+")", Math.abs(M.periodDays/E.periodDays-1.88)<0.005);
check("Earth au=1", E.auRadius===1.0 && M.auRadius>1.4 && M.auRadius<1.6);
check("stay+ida+volta=total", Math.abs(m.outboundDays+m.stayDays+m.returnDays-m.totalDays)<1e-9);

// 5) consistência: ângulo declarado vs. posição real de Marte à partida
var leadActual = au(M,0);
var ang = Math.atan2(leadActual.y, leadActual.x)*180/Math.PI;
check("declared lead == actual Mars angle0", Math.abs(((ang - E.angleDeg0 + 360)%360) - m.departurePhaseAngleDeg) < 1e-6);

// 6) nave no dia 0 na Terra
b.setMissionDay(0); s=b.getState();
check("ship==Earth @ 0", dist(s.shipAU, au(E,0)) < 1e-9);

// 7) ponto intermédio da ida: raio entre 1 e 1.524 e ângulo < 180
b.setMissionDay(m.outboundDays/2); s=b.getState();
var r=Math.hypot(s.shipAU.x,s.shipAU.y);
check("mid-outbound r∈(1,1.524)  r="+r.toFixed(3), r>1.0 && r<1.524);
console.log(fails? "FALHOU "+fails : "TODOS OS TESTES PASSARAM");
process.exit(fails?1:0);
'

